"""Real owned files/syscalls and abrupt process exit; never a machine-power-loss claim."""
import hashlib,json,os,pathlib,subprocess,sys,tempfile

class NativeOps:
    def __init__(self,root,stop):self.root=pathlib.Path(root);self.target=self.root/'target';self.temp=self.root/'pending';self.stop=stop;self.fd=None;self.trace=[];self.unsafe=False
    def record(self,event):
        self.trace.append(event)
        row={'event':event,'target_sha256':hashlib.sha256(self.target.read_bytes()).hexdigest(),'pending_exists':self.temp.exists()}
        print('NATIVE_STAGE:'+json.dumps(row),flush=True)
        if self.stop==event:os._exit(77)
    def begin(self):
        if self.fd is not None:raise ValueError('transaction already open')
        self.fd=os.open(self.temp,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600);self.record('begin')
    def write(self,data):
        if self.fd is None:raise ValueError('transaction not open')
        middle=max(1,len(data)//2)
        for number,chunk in enumerate((data[:middle],data[middle:])):
            view=memoryview(chunk)
            while view:
                written=os.write(self.fd,view);view=view[written:]
            if number==0:self.record('partial_write')
        self.record('write_complete')
    def sync_data(self):os.fsync(self.fd);self.record('data_sync')
    def commit(self):
        if self.fd is not None:os.close(self.fd);self.fd=None
        os.replace(self.temp,self.target);self.record('rename')
    def sync_directory(self):
        fd=os.open(self.root,os.O_RDONLY|os.O_DIRECTORY)
        try:os.fsync(fd)
        finally:os.close(fd)
        self.record('directory_sync')
    def in_place(self,data):
        # Intentionally unsafe operation is available to reproduce the bad protocol.
        self.unsafe=True;self.fd=os.open(self.target,os.O_WRONLY|os.O_TRUNC);self.write(data)
    def close(self):
        if self.fd is not None:os.close(self.fd);self.fd=None
        self.temp.unlink(missing_ok=True)

def child():
    request=json.load(sys.stdin);root=pathlib.Path(request['root']);sys.path.insert(0,str(pathlib.Path.cwd()));import task
    ops=NativeOps(root,request['stop'])
    try:task.update(ops,bytes.fromhex(request['new_hex']))
    except BaseException as error:
        print('NATIVE_CHILD_ERROR:'+json.dumps({'type':type(error).__name__,'message':str(error),'errno':getattr(error,'errno',None)}),flush=True);raise
    print('NATIVE_COMPLETED:'+json.dumps({'trace':ops.trace,'temp_exists':ops.temp.exists()}),flush=True)

def scenario(new,stop):
    before=(os.getuid(),os.environ.get('HOME'),os.environ.get('PATH'));old=b'OLD-CONSISTENT-'+b'o'*8192
    with tempfile.TemporaryDirectory(prefix='of-crash-protocol-')as directory:
        root=pathlib.Path(directory);target=root/'target'
        with target.open('wb')as handle:handle.write(old);handle.flush();os.fsync(handle.fileno())
        command=[sys.executable,'-B',str(pathlib.Path(__file__).resolve()),'child'];proc=subprocess.Popen(command,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
        try:stdout,stderr=proc.communicate(json.dumps({'root':str(root),'stop':stop,'new_hex':new.hex()}).encode(),timeout=4)
        except subprocess.TimeoutExpired:proc.kill();proc.communicate(timeout=2);raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: owned protocol child deadline')
        output=stdout.decode(errors='replace');events=[json.loads(line.split(':',1)[1])for line in output.splitlines()if line.startswith('NATIVE_STAGE:')]
        errors=[json.loads(line.split(':',1)[1])for line in output.splitlines()if line.startswith('NATIVE_CHILD_ERROR:')]
        if errors:
            if errors[-1]['type']=='NotImplementedError':raise NotImplementedError(errors[-1]['message'])
            if errors[-1]['type']=='AssertionError':raise AssertionError(errors[-1]['message'])
            raise RuntimeError('Student/native child failure: '+json.dumps(errors[-1]))
        reader=subprocess.run([sys.executable,'-B','-c','import json,pathlib,sys; p=pathlib.Path(sys.argv[1]); print(json.dumps({"hex":p.read_bytes().hex(),"inode":p.stat().st_ino}))',str(target)],capture_output=True,timeout=3)
        if reader.returncode!=0:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: fresh recovery reader failed')
        recovered=json.loads(reader.stdout);data=bytes.fromhex(recovered['hex']);state='old'if data==old else'new'if data==new else'invalid'
        result={'stop':stop,'owned_pid':proc.pid,'exit_code':proc.returncode,'reaped':proc.poll()is not None,'recovery_fresh_process':True,'state':state,'old_sha256':hashlib.sha256(old).hexdigest(),'new_sha256':hashlib.sha256(new).hexdigest(),'recovered_sha256':hashlib.sha256(data).hexdigest(),'events':events,'completed':'NATIVE_COMPLETED:'in output,'stderr':stderr.decode(errors='replace')}
    assert before==(os.getuid(),os.environ.get('HOME'),os.environ.get('PATH'));result['owned_directory_removed']=not root.exists();result['parent_identity_environment_unchanged']=True;return result

if __name__=='__main__':
    if sys.argv[1:]!=['child']:raise SystemExit('owned child mode only')
    child()

